// Extract the raw text output from the AI Agent
let rawOutput = $input.first().json.output || "";

// Clean up markdown formatting
let cleanJsonString = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsedData = {};

try {
  parsedData = JSON.parse(cleanJsonString);
} catch (error) {
  parsedData = {
    "immediate_assistance_needed": false,
    "sufficient_information": false,
    "follow_up_question": "I'm setting up our session. Could you tell me what made you decide to seek support today?",
    "error_log": "Failed to parse JSON"
  };
}

return { json: parsedData };
